@@ -0,0 +1,24 @@
+// A request-scoped view keeps site-owned records in their original store.
+/** Returns a store view containing only records belonging to a site. */
+export function siteStore(store, site) {
+  const locations = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  const scoped = (key, predicate) => {
+    const source = store.data[key] ?? (store.data[key] = []);
+    const view = source.filter(predicate);
+    Object.defineProperty(view, "push", { value: (...records) => source.push(...records) });
+    return view;
+  };
+  const data = new Proxy(store.data, {
+    get(target, key) {
+      if (key === "locations") return scoped(key, (l) => locations.has(l.id));
+      if (key === "batches") return scoped(key, (b) => locations.has(b.location));
+      if (key === "stocktakes" || key === "temperatures") return scoped(key, (r) => locations.has(r.location));
+      if (key === "movements") {
+        const batches = new Set(target.batches.filter((b) => locations.has(b.location)).map((b) => b.id));
+        return scoped(key, (m) => batches.has(m.batchId));
+      }
+      return target[key];
+    },
+  });
+  return { data, nextId: store.nextId.bind(store), save: store.save.bind(store) };
+}
